import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import stringToColor from 'flarum/common/utils/stringToColor';
import humanTime from 'flarum/common/utils/humanTime';
import { t, tx } from '../api';

/** Small pieces both pages use. People are plain objects from our endpoints, not store models. */

export function Face(_) {
  return {
    view: ({
      attrs
    }) => {
      const {
        person
      } = attrs;
      const className = 'Avatar SecretSanta-face' + (attrs.size ? ' SecretSanta-face--' + attrs.size : '');
      return person.avatar ? m("img", {
        className: className,
        src: person.avatar,
        alt: person.name,
        title: person.name,
        loading: attrs.size === 'large' ? 'eager' : 'lazy'
      }) : m("span", {
        className: className,
        style: {
          '--avatar-bg': '#' + stringToColor(person.name)
        },
        role: "img",
        "aria-label": person.name,
        title: person.name
      }, person.name.charAt(0).toUpperCase());
    }
  };
}
export function PersonLink(_) {
  return {
    view: ({
      attrs
    }) => attrs.person ? m(Link, {
      className: "SecretSanta-person",
      href: app.route('user', {
        username: attrs.person.slug
      })
    }, m(Face, {
      person: attrs.person
    }), m("span", {
      className: "SecretSanta-personName"
    }, attrs.person.name)) : m("span", {
      className: "SecretSanta-person"
    }, app.translator.trans('core.lib.username.deleted_text'))
  };
}
export function Faces(_) {
  return {
    view: ({
      attrs
    }) => {
      const more = attrs.total - attrs.people.length;
      return m("span", {
        className: "SecretSanta-faces",
        "aria-label": tx('card.members', {
          count: attrs.total
        })
      }, attrs.people.map(person => m(Face, {
        person: person,
        size: "small"
      })), more > 0 && m("span", {
        className: "SecretSanta-facesMore"
      }, "+", more));
    }
  };
}
const STATUS_ICONS = {
  open: 'fas fa-pen-to-square',
  drawn: 'fas fa-shuffle',
  active: 'fas fa-truck-fast',
  complete: 'fas fa-circle-check'
};
export function StatusPill(_) {
  return {
    view: ({
      attrs
    }) => m("span", {
      className: 'SecretSanta-status SecretSanta-status--' + attrs.status
    }, m(Icon, {
      name: STATUS_ICONS[attrs.status]
    }), " ", t(`status.${attrs.status}`))
  };
}
export function kindIcon(kind) {
  return kind === 'digital' ? 'fas fa-gamepad' : 'fas fa-box';
}

/** "in 3 days" / "3 days ago". Core's humanTime turns every future time into "just now", and deadlines are in the future. */
export function when(iso) {
  return dayjs(iso).isAfter(dayjs()) ? dayjs(iso).fromNow() : humanTime(iso);
}
export function day(date) {
  return dayjs(date).format('ll');
}
export function moment(iso) {
  return dayjs(iso).format('lll');
}
/** Plain text with line breaks kept; never HTML. */
export function Text(_) {
  return {
    view: ({
      attrs
    }) => attrs.text ? m("div", {
      className: 'SecretSanta-text ' + (attrs.className || '')
    }, attrs.text) : null
  };
}
flarum.reg.add('ernestdefoe-secret-santa', 'forum/components/bits', { Face: Face,PersonLink: PersonLink,Faces: Faces,StatusPill: StatusPill,kindIcon: kindIcon,when: when,day: day,moment: moment,Text: Text, });